    31	const PROCESSING_FEE = 5;
    32	const FIRST_INSURANCE_SURCHARGE = 0.1;
    33	const FOLLOW_UP_DISCOUNT = 0.15;
    34	const LOYALTY_DISCOUNT = 0.2;
    35	const LOYALTY_YEARS = 2;
    36	const CURSE_SURCHARGE = 0.5;
    37	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
    38	const HIGH_ENCHANTMENT_PREMIUM_THRESHOLD = 5;
    39	
    40	const MAIN_ITEMS: Record<string, { value: number; basePremium: number }> = {
    41	  sword: { value: 1000, basePremium: 100 },
    42	  amulet: { value: 600, basePremium: 60 },
    43	  staff: { value: 800, basePremium: 80 },
    44	  potion: { value: 400, basePremium: 40 },
    45	};
    46	
    47	const COMPONENTS = new Set(['rune', 'moonstone']);
    48	const COMPONENT_VALUE = 250;
    49	const COMPONENT_BASE_PREMIUM = 25;
    50	const BLOCK_SIZE = 3;
    51	const BLOCK_BASE_PREMIUM = 60;
    52	
    53	function componentsBasePremium(components: Item[]): number {
    54	  const countsByType = new Map<string, number>();
    55	  for (const component of components) {
    56	    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
    57	  }
    58	  let total = 0;
    59	  for (const count of countsByType.values()) {
    60	    total += count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
    61	  }
    62	  return total;
    63	}
    64	
    65	function assertKnownType(type: string): void {
    66	  if (!Object.hasOwn(MAIN_ITEMS, type) && !COMPONENTS.has(type)) {
    67	    throw new Error(`Unknown item type: ${type}`);
    68	  }
    69	}
