    71	function quotePremium(items: Item[], yearsWithMHPCO: number, isFollowUp: boolean): number {
    72	  items.forEach((item) => assertKnownType(item.type));
    73	  const components = items.filter((item) => COMPONENTS.has(item.type));
    74	  const mainItems = items.filter((item) => !COMPONENTS.has(item.type));
    75	  const policyBase =
    76	    mainItems.reduce((sum, item) => sum + MAIN_ITEMS[item.type].basePremium, 0) +
    77	    componentsBasePremium(components);
    78	  const itemSurcharges = mainItems.reduce((sum, item) => {
    79	    const base = MAIN_ITEMS[item.type].basePremium;
    80	    const curse = item.cursed ? base * CURSE_SURCHARGE : 0;
    81	    const highEnchantment =
    82	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_PREMIUM_THRESHOLD
    83	        ? base * HIGH_ENCHANTMENT_SURCHARGE
    84	        : 0;
    85	    return sum + curse + highEnchantment;
    86	  }, 0);
    87	  const loyalty = yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_DISCOUNT : 0;
    88	  const followUp = isFollowUp ? FOLLOW_UP_DISCOUNT : 0;
    89	  const policyModifier = FIRST_INSURANCE_SURCHARGE - loyalty - followUp;
    90	  const total = policyBase + itemSurcharges + policyBase * policyModifier + PROCESSING_FEE;
    91	  return Math.ceil(total);
    92	}
    93	
    94	const DEDUCTIBLE = 100;
    95	const CAP_FACTOR = 2;
    96	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
    97	const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
    98	
    99	interface Policy {
   100	  items: Item[];
   101	  remainingCap: number;
   102	}
   103	
   104	function insuranceValue(item: Item): number {
   105	  return COMPONENTS.has(item.type) ? COMPONENT_VALUE : MAIN_ITEMS[item.type].value;
   106	}
   107	
   108	function reimbursement(item: Item, amount: number): number {
   109	  const rate =
   110	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD ? HIGH_ENCHANTMENT_REIMBURSEMENT : 1;
   111	  return Math.max(0, amount * rate - DEDUCTIBLE);
   112	}
   113	
   114	function processClaim(policy: Policy, damages: Damage[]): { payout: number; remainingCap: number } {
   115	  const unclaimed = [...policy.items];
   116	  const desired = damages.reduce((sum, damage) => {
   117	    if (damage.amount < 0) {
   118	      throw new Error(`Invalid damage amount: ${damage.amount}`);
   119	    }
   120	    const index = unclaimed.findIndex((candidate) => candidate.type === damage.itemType);
   121	    if (index === -1) {
   122	      throw new Error(`Damaged item not covered by policy: ${damage.itemType}`);
   123	    }
   124	    const [item] = unclaimed.splice(index, 1);
   125	    return sum + reimbursement(item, damage.amount);
   126	  }, 0);
   127	  const payout = Math.min(Math.floor(desired), policy.remainingCap);
   128	  policy.remainingCap -= payout;
   129	  return { payout, remainingCap: policy.remainingCap };
   130	}
   131	
   132	export function runScenario(scenario: Scenario): { results: Result[] } {
   133	  let contractsSoFar = 0;
   134	  const policies = new Map<number, Policy>();
   135	  return {
   136	    results: scenario.steps.map((step, index) => {
   137	      if (step.op === 'claim') {
   138	        const policy = policies.get(step.policy);
   139	        if (!policy) throw new Error(`Unknown policy: ${step.policy}`);
   140	        return processClaim(policy, step.incident.damages);
   141	      }
   142	      const premium = quotePremium(step.items, scenario.customer.yearsWithMHPCO, contractsSoFar > 0);
   143	      contractsSoFar++;
   144	      const insuranceSum = step.items.reduce((sum, item) => sum + insuranceValue(item), 0);
   145	      policies.set(index, { items: step.items, remainingCap: insuranceSum * CAP_FACTOR });
   146	      return { premium };
   147	    }),
   148	  };
   149	}
